const q = $('Webhook').first().json.query || {};
const items = $input.all();

// Single-artifact mode (type provided)
if (q.type) {
  const first = items[0] ? items[0].json : null;

  let artifact = first;
  if (artifact && typeof artifact === 'object') {
    const keys = Object.keys(artifact);
    if (keys.length === 1 && keys[0] === 'success') {
      artifact = null;
    }
  }

  const ok = !!(artifact && typeof artifact === 'object' && (artifact.id || artifact.type || artifact.version));
  return [{ json: { ok, artifact } }];
}

// List mode (no type): return latest per artifact type
const artifacts = items
  .map(i => i.json)
  .filter(r => r && typeof r === 'object' && r.type);

// Deterministic ordering for polling
artifacts.sort((a,b) => String(a.type).localeCompare(String(b.type)));

const present = new Set(artifacts.map(a => a.type));

// Completion criteria for sequential pipeline incl. security + solution + QA + PRD.
const requiredTypes = [
  'brd',
  'business_arch',
  'application_arch',
  'data_arch',
  'infrastructure_arch',
  'archimate_xml_business_application_data_infra',
  'risk_assessment_md',
  'solution_arch_md',
  'test_strategy_md',
  'test_scenarios_md',
  'prd_md',
];

const missingTypes = requiredTypes.filter(t => !present.has(t));
const complete = missingTypes.length === 0;

return [{
  json: {
    ok: true,
    artifacts,
    count: artifacts.length,
    complete,
    requiredTypes,
    missingTypes,
  }
}];
